begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('e1000000-0000-0000-0000-000000000001','automation-owner@test.invalid'),('e1000000-0000-0000-0000-000000000002','automation-other@test.invalid');
insert into public.tenants(id,name,slug)values('e2000000-0000-0000-0000-000000000001','Automation A','automation-a'),('e2000000-0000-0000-0000-000000000002','Automation B','automation-b');
insert into public.properties(id,tenant_id,name,property_type)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Hotel A','hotel'),('e3000000-0000-0000-0000-000000000002','e2000000-0000-0000-0000-000000000002','Hotel B','hotel');
insert into public.tenant_memberships(tenant_id,user_id,role)values('e2000000-0000-0000-0000-000000000001','e1000000-0000-0000-0000-000000000001','owner'),('e2000000-0000-0000-0000-000000000002','e1000000-0000-0000-0000-000000000002','owner');
insert into public.guests(id,tenant_id,full_name,phone)values('e4000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','Asha','+919111111111');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency,created_at)values('e5000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','confirmed',current_date,current_date+2,5000,'INR',now()-interval '1 day');
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,display_phone,credentials_ref)values('e6000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','12345678001','12345678002','+919999999999','automation-test');
set local role service_role;
select is(public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[{"provider_id":"12345","name":"stay_update","language":"en_US","category":"utility","provider_status":"APPROVED","body":"Hi {{1}} from {{2}}. {{3}}","parameter_names":["1","2","3"],"supported":true,"definition":{"components":[{"type":"BODY","text":"Hi {{1}} from {{2}}. {{3}}"}]}}]'),1,'provider template synced');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select set_config('test.auto_template',(select id::text from public.message_templates where property_id='e3000000-0000-0000-0000-000000000001'and name='stay_update'),true);
select throws_ok($$select public.whatsapp_automation_workspace('e3000000-0000-0000-0000-000000000002')$$,'42501',null,'other hotel automation access denied');
select public.save_whatsapp_automation_rule('e3000000-0000-0000-0000-000000000001','checked_in',0,true,current_setting('test.auto_template')::uuid,'["guest_name","hotel_name","portal_url"]',0);
select throws_ok($$select public.save_whatsapp_automation_rule('e3000000-0000-0000-0000-000000000001','checked_in',0,true,current_setting('test.auto_template')::uuid,'[]',0)$$,'40001',null,'stale rule update denied');
reset role;
update public.reservations set status='checked_in',checked_in_at=now()where id='e5000000-0000-0000-0000-000000000001';
update public.reservations set status='checked_in'where id='e5000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from public.whatsapp_automation_events where event_key='checked_in'and property_id='e3000000-0000-0000-0000-000000000001'),1,'confirmed transition emits one durable event');
set local role service_role;
select is(public.dispatch_whatsapp_automations(50,'https://guest.test'),0,'no booking phone can bypass permission');
select is((select state from public.whatsapp_automation_events where event_key='checked_in'and property_id='e3000000-0000-0000-0000-000000000001'),'blocked','missing permission is explained');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e1000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.authorize_whatsapp_stay_updates('e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001',0,'granted','Guest verified phone and signed the stay-update opt-in.',true);
reset role;
update public.whatsapp_automation_events set next_check_at=now()where property_id='e3000000-0000-0000-0000-000000000001';
set local role service_role;
select is(public.dispatch_whatsapp_automations(50,'https://guest.test'),1,'permitted guest receives one queued personalized template');
select is(public.dispatch_whatsapp_automations(50,'https://guest.test'),0,'repeat dispatcher does not duplicate');
select is((select count(*)::integer from public.guest_access_tokens where reservation_id='e5000000-0000-0000-0000-000000000001'),1,'secure portal link issued once');
select ok((select body like 'Hi Asha from Hotel A. https://guest.test/s/%'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'),'rendered snapshot contains guest data and secure stay link');
select is((select count(*)::integer from public.claim_outbound_messages_v3(10,false)),0,'old workers cannot strip automation parameters');
select is((select count(*)::integer from public.claim_outbound_messages_v4(10,false,false)),0,'automation delivery flag is required');
select is((select count(*)::integer from public.claim_outbound_messages_v4(10,false,true)),1,'new worker claims automation');
select is((select jsonb_array_length(template_components->0->'parameters')from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'),3,'all provider parameters frozen in queue');
insert into public.consent_records(property_id,tenant_id,wa_contact_id,status,source)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','919111111111','opted_out','keyword');
select is((select(public.validate_outbound_claim(id,attempts)->>'ok')::boolean from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'),false,'STOP after queue suppresses delivery');
reset role;
-- Activate all other utility events for capture coverage, but do not send anything.
insert into public.whatsapp_automation_rules(property_id,tenant_id,event_key,enabled,template_id,template_fingerprint,parameter_keys)
select 'e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001',x->>'key',true,t.id,t.provider_fingerprint,'["guest_name","hotel_name","event_label"]'::jsonb from jsonb_array_elements(public.whatsapp_automation_catalog())x cross join public.message_templates t where t.id=current_setting('test.auto_template')::uuid and x->>'key'not in('checked_in','review_request')on conflict do nothing;
insert into public.orders(id,tenant_id,property_id,kind,reservation_id,total)values('e7000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','room_service','e5000000-0000-0000-0000-000000000001',450);
update public.orders set status='preparing'where id='e7000000-0000-0000-0000-000000000001';update public.orders set status='ready'where id='e7000000-0000-0000-0000-000000000001';update public.orders set status='served'where id='e7000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from public.whatsapp_automation_events where source_table='orders'and property_id='e3000000-0000-0000-0000-000000000001'),4,'all dining milestones captured');
insert into public.guest_requests(id,tenant_id,property_id,reservation_id,title,source)values('e8000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001','Fresh towels','portal');
insert into public.tasks(id,tenant_id,property_id,title,guest_request_id,reservation_id)values('e9000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','Internal staff notes must never be shared','e8000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001');
update public.tasks set status='done'where id='e9000000-0000-0000-0000-000000000001';update public.guest_requests set status='completed'where id='e8000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from public.whatsapp_automation_events where event_key='request_completed'and property_id='e3000000-0000-0000-0000-000000000001'),1,'task and request completion deduplicate');
select ok(not exists(select 1 from public.whatsapp_automation_events where payload::text like '%Internal staff notes%'),'internal task title is not shared');
insert into public.tasks(tenant_id,property_id,title,status)values('e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','Clean empty room','done');
select is((select count(*)::integer from public.whatsapp_automation_events where event_key='request_completed'and property_id='e3000000-0000-0000-0000-000000000001'),1,'unrelated housekeeping task emits no guest event');
select set_config('test.auto_folio',(select id::text from public.folios where reservation_id='e5000000-0000-0000-0000-000000000001'),true);
insert into public.payments(id,tenant_id,property_id,folio_id,amount,method)values('eb000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001',current_setting('test.auto_folio')::uuid,500,'cash');
insert into public.refunds(tenant_id,property_id,payment_id,amount,reason)values('e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','eb000000-0000-0000-0000-000000000001',100,'Guest refund');
insert into public.invoices(tenant_id,property_id,folio_id,number,total,currency)values('e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001',current_setting('test.auto_folio')::uuid,'AUTO-1',400,'INR');
select is((select count(*)::integer from public.whatsapp_automation_events where event_key in('payment_received','payment_refunded','invoice_issued')and property_id='e3000000-0000-0000-0000-000000000001'),3,'payment, refund and invoice captured');
select is((select payload->>'amount'from public.whatsapp_automation_events where event_key='payment_received'and property_id='e3000000-0000-0000-0000-000000000001'),'500.00','payment amount is its own receipt amount');
set local role service_role;
select lives_ok($$select public.dispatch_whatsapp_automations(50,'https://guest.test')$$,'scheduled reminder generator and all eligibility checks run');
reset role;

select is((select count(*)::integer from public.whatsapp_automation_events where event_key='checkout_reminder'and property_id='e3000000-0000-0000-0000-000000000001'),1,'future checkout reminder scheduled once');
select is((select state from public.whatsapp_automation_events where event_key='order_placed'and property_id='e3000000-0000-0000-0000-000000000001'),'skipped','obsolete dining update suppressed');
set local role authenticated;
select throws_ok($$select public.dispatch_whatsapp_automations(10,'https://guest.test')$$,'42501',null,'clients cannot dispatch guest messages');
select throws_ok($$select public.sync_whatsapp_provider_templates('e6000000-0000-0000-0000-000000000001','12345678002','[]')$$,'42501',null,'clients cannot forge provider approval');
reset role;
insert into public.consent_records(property_id,tenant_id,wa_contact_id,status,source)values('e3000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','919111111111','opted_in','keyword');
update public.conversations set human_handoff=true where property_id='e3000000-0000-0000-0000-000000000001';
select is((select public.validate_outbound_claim(id,attempts)->>'error'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Conversation is under human handling or resolved.','human handoff suppresses claimed automation');
update public.conversations set human_handoff=false where property_id='e3000000-0000-0000-0000-000000000001';
update public.guests set phone='+919222222222'where id='e4000000-0000-0000-0000-000000000001';
select is((select public.validate_outbound_claim(id,attempts)->>'error'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Guest phone changed.','guest phone changes require new verified authorization');
update public.guests set phone='+919111111111'where id='e4000000-0000-0000-0000-000000000001';
update public.message_templates set provider_checked_at=now()-interval '25 hours'where id=current_setting('test.auto_template')::uuid;
select is((select public.validate_outbound_claim(id,attempts)->>'error'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Approved template changed, unavailable or sync is stale.','stale provider approval blocks delivery');
update public.message_templates set provider_checked_at=now()where id=current_setting('test.auto_template')::uuid;
update public.whatsapp_guest_authorizations set status='revoked'where property_id='e3000000-0000-0000-0000-000000000001';
select is((select public.validate_outbound_claim(id,attempts)->>'error'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Guest stay-update permission missing or revoked.','permission revocation blocks an already claimed message');
update public.whatsapp_guest_authorizations set status='granted'where property_id='e3000000-0000-0000-0000-000000000001';
insert into public.guest_documents(id,tenant_id,property_id,reservation_id,guest_id,doc_type,storage_path,mime_type,size_bytes)values('ec000000-0000-0000-0000-000000000001','e2000000-0000-0000-0000-000000000001','e3000000-0000-0000-0000-000000000001','e5000000-0000-0000-0000-000000000001','e4000000-0000-0000-0000-000000000001','passport','private/synthetic-document.pdf','application/pdf',100);
update public.guest_documents set status='uploaded'where id='ec000000-0000-0000-0000-000000000001';update public.guest_documents set status='approved'where id='ec000000-0000-0000-0000-000000000001';
select is((select count(*)::integer from public.whatsapp_automation_events where source_table='guest_documents'and property_id='e3000000-0000-0000-0000-000000000001'),2,'document received and reviewed milestones captured');
select ok(not exists(select 1 from public.whatsapp_automation_events where payload::text like '%synthetic-document.pdf%'or payload::text like '%passport%'),'private document identifiers never enter template data');
update public.whatsapp_automation_events set expires_at=now()-interval '1 second'where event_key='checked_in'and property_id='e3000000-0000-0000-0000-000000000001';
select is((select public.validate_outbound_claim(id,attempts)->>'error'from public.messages where automation_event_id is not null and property_id='e3000000-0000-0000-0000-000000000001'limit 1),'Event expired.','expired automation is not sent');

select *from finish();rollback;
